INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a','db618e68-0656-4b9b-b308-81e071faf745','Vorlenien "Vorlag" Hochmeister','complete','{"age":"","era":"","name":"Vorlenien \"Vorlag\" Hochmeister","race":"","alias":"King","gender":"Male","titles":"King of Shadowfen","subrace":"","summary":"King Vorlenien \"Vorlag\" Hochmeister is the ruler of Shadowfen and wielder of the great runic magic inherited through his male bloodline. After his noble family was stripped of its status and later massacred in a fire secretly orchestrated by The Church, his dormant runic power awakened through overwhelming trauma. Raised and manipulated by The Church afterward, Vorlag pursued vengeance, power, and kingship while believing the prophecy surrounding his Runes of Dominion represented his true destiny.","heritage":"","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"Vorlag","occupation":"King","affiliation":"Shadowfen","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Shadowfen","elementalHeritage":""}','{"build":["Tall","Lean-muscular","Broad-shouldered"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Piercing blue"],"grooming":"","skinTone":["Pale"],"wardrobe":"","hairColor":["Black"],"hairStyle":"","accessories":"","faceDetails":["Sharp jawline","Angular features","Strong brows"],"hairTexture":"","colorPalette":"","dominantHand":"","outfitColors":"","alternateForm":"","clothingStyle":"","appearanceNotes":"","outfitMaterials":"","postureMovement":["Regal","Controlled","Commanding"],"signatureOutfit":"","distinguishingFeatures":""}','{"fears":["Losing his family","Powerlessness","Failing to protect Theron","Losing control"],"goals":["Secure Shadowfen","Strengthen his rule","Fulfill his perceived destiny"],"beliefs":["Power ensures protection","Control prevents chaos","His runes mark his destiny","He is destined to rule"],"culture":"","lineage":"Hochmeister noble bloodline","storyArc":"Vorlag''s tragedy begins with a child desperate to protect his family and develops into a ruler who equates safety with absolute control. His vengeance and rise to power appear self-directed, but both were cultivated by The Church. The eventual truth behind his family''s massacre threatens the foundation of his identity, kingship, and belief in his destiny.","backstory":"At twelve, Vorlag returned with Vex, Corvin Sterling, and Alistar Vane to find the Hochmeister home engulfed in flames. Hearing his family trapped inside triggered the violent awakening of his inherited runic magic, forcing Vex to knock him unconscious before the uncontrolled eruption worsened. The massacre had secretly been engineered by The Church to awaken Vorlag''s power and advance a prophecy surrounding the Runes of Dominion. Church agents subsequently sheltered and trained him while directing his vengeance toward the nobles they had used as puppets. Vorlag eventually rose to kingship, married Isolde, established Shadowfen as his seat of power, and extended his influence into Ironspire Hold and the Lionheart Plains while remaining unaware of the full extent of The Church''s manipulation.","childhood":"Vorlag was born into a high-ranking noble family and displayed exceptional intellect from childhood. At age six, rival nobles stripped his family of its position and reduced them to commoners. He witnessed repeated humiliation and abuse directed toward his family and learned that openly resisting their aggressors could bring even greater retaliation.","lifestyle":["Royal governance","Military oversight","Runic training"],"storyRole":"Vorlag serves as the tyrannical King of Shadowfen while unknowingly remaining a central piece in The Church''s long-term plan. His rule, runic inheritance, and manipulated prophecy connect him to the artifact that Elias Thorne will eventually seek to protect.","birthplace":"","psychology":["Deep fear of helplessness","Obsessed with control","Protection through power","Unresolved family grief","Trauma-driven vigilance","Righteous self-justification"],"motivations":["Protect his family","Prevent future helplessness","Maintain absolute control","Fulfill the Dominion prophecy","Preserve Shadowfen"],"personality":["Intelligent","Calculating","Protective","Driven","Controlling","Ruthless","Traumatized","Determined","Suspicious"],"voiceSpeech":["Commanding","Controlled","Authoritative"],"likesDislikes":"","majorLifeEvents":"Born into House Hochmeister\nFamily stripped of noble status\nFamily reduced to commoners\nWitnessed repeated family abuse\nAttempted to defend his family\nHochmeister home burned\nFamily killed in the fire\nRunic magic awakened\nTaken in by The Church\nTrained by The Church\nHunted the responsible nobles\nFalsely accused of killing his family\nPursued the Dominion prophecy\nMarried Isolde\nBecame King\nEstablished Shadowfen"}','{"weapons":"","strengths":"Exceptional intellect\nRunic power\nStrategic planning\nStrong will\nPolitical authority","weaknesses":"Unresolved trauma\nFear of helplessness\nProtective obsession\nSusceptibility to Church manipulation","combatStyle":"","limitations":["Runes were initially uncontrollable"],"powerSource":["Hochmeister bloodline","Great Runic Magic"],"abilityNotes":"The great runic magic passes through the male Hochmeister bloodline. Vorlag''s abilities remained dormant until the destruction of his family triggered their violent awakening at age twelve.","combatProfile":"Vorlag possesses powerful hereditary runic magic awakened through extreme trauma. His Runes of Dominion form the supernatural foundation of his authority and are central to the prophecy cultivated around him by The Church.","weaponDetails":"","transformations":"","primaryAbilities":"Runic Magic\nRunes of Dominion","secondaryAbilities":"","signatureTechniques":"","transformationDetails":""}','{"allies":"Count Vex\nLord Corvin Sterling\nLord Alistar Vane","rivals":"","enemies":"","mentors":"","parents":"","partner":"Isolde","children":"Theron","siblings":"","worldConnections":"Shadowfen\nIronspire Hold\nLionheart Plains","relationshipNotes":"Vex, Corvin Sterling, and Alistar Vane were Vorlag''s closest childhood friends and remained central figures in his rise. Vex helped keep him level-headed through cynical distraction, Corvin brought humor during their childhood, and Alistar provided intellectual and physical motivation. The Church later positioned itself as Vorlag''s benefactor while secretly having engineered the destruction of his family."}','{"tbdFields":"","canonLocks":"Black hair\nPiercing blue eyes\nTall build\nLean-muscular build\nBroad shoulders\nRegal presence","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a/portrait/1790363520697-vorlag-character-portrait.png","visualAssets":"Character Portrait — Done","productionNotes":"","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a/reference/1790363526757-vorlag-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a/alternate/1790363531960-vorlag-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/3fd4e4a6-bb47-4ed5-9d1f-cae8636d7a3a/portrait/1790363520697-vorlag-character-portrait.png',6,1,1,NULL,NULL,'74fb0163-f452-4f7e-a9ea-13c15bb960db','959ee89b-1d60-47e4-b017-93d8ade67726','2026-09-25T19:27:26.037429+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('b317848b-4cba-46fa-8807-4c9ffd26392e','db618e68-0656-4b9b-b308-81e071faf745','Herabelle','complete','{"age":"","era":"500–1300 AD-inspired","name":"Herabelle","race":"Human","alias":"","gender":"Female","titles":"The Shadow of the Forge\nDevoted Protector","subrace":"","summary":"Herabelle is a beautiful, highly devoted protector whose loyalty to Alistair borders on worship. She serves as the finesse beside his overwhelming force, using speed, precision, and chained weaponry to control threats around him. Her affection becomes dangerous when jealousy or perceived threats to Alistair overwhelm her judgment.","heritage":"","homeland":"","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"Protector","affiliation":"","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":""}','{"build":["Slender","Athletic","Agile"],"nails":"","eyeHex":["Green — #6F8F65"],"height":"","makeup":["Subtle eye definition","Natural lips"],"weight":"","hairHex":["Blonde — #D8B985"],"skinHex":["Fair — #E8C9B8"],"eyeColor":["Green"],"grooming":"Feminine and carefully maintained","skinTone":["Fair"],"wardrobe":"Neutral combat attire\nDark leather armor\nIvory underlayers\nTall leather boots\nFingerless gloves","hairColor":["Blonde"],"hairStyle":"Long flowing blonde hair","accessories":"Forge-soot vial necklace\nLeather belts\nMetal chains\nForge-inspired jewelry","faceDetails":["Soft feminine features","Refined jawline","Delicate nose","Expressive eyes"],"hairTexture":["Soft","Lightly tousled"],"colorPalette":"Ivory — #E6DDD0\nCharcoal — #211F1E\nBlack — #0D0D0E\nLeather Brown — #49372C\nSteel — #A9B3BA\nRune Blue — #8DD9ED","dominantHand":"","outfitColors":"Ivory\nCharcoal\nBlack\nDark brown\nSteel","alternateForm":"","clothingStyle":"Herabelle wears elegant medieval-fantasy combat clothing built around neutral colors and dark leather. Fitted protection, layered fabrics, belts, chains, and subtle gothic detailing complement her graceful fighting style without restricting movement.","appearanceNotes":"Herabelle initially looks like an exceptionally beautiful and seemingly ordinary blonde human woman. Her green eyes become noticeably softer and gain a subtle twinkle when she looks at Alistair. Her combat expressions create a sharp contrast with her otherwise graceful appearance.","outfitMaterials":["Leather","Linen","Metal","Chain","Lace"],"postureMovement":["Graceful","Fluid","Acrobatic","Predatory"],"signatureOutfit":"A fitted neutral-toned fantasy combat ensemble with an ivory underlayer, dark leather corsetry, layered fabric, belts, straps, gloves, and tall boots. The silhouette remains feminine and elegant while allowing unrestricted acrobatic movement.","distinguishingFeatures":["Intense sanpaku gaze","Softened gaze around Alistair","Elegant combat silhouette"]}','{"fears":["Losing Alistair","Separation from Alistair"],"goals":["Keep Alistair safe","Remain useful to Alistair","Fight beside Alistair"],"beliefs":["Alistair is extraordinary","His creations are sacred","Protection proves devotion"],"culture":"","lineage":"","storyArc":"Herabelle''s arc explores the dangerous boundary between devotion, possession, and protection. Her loyalty makes her an invaluable defender, but her distorted interpretation of Alistair''s affection can become unstable whenever she believes their bond is threatened.","backstory":"Herabelle became deeply devoted to Alistair and established herself as his protector. Her attachment developed beyond ordinary loyalty, causing her to treat his craftsmanship, words, and gifts with almost sacred reverence. She quietly handles perceived threats around him rather than burdening him with every confrontation.","childhood":"","lifestyle":["Stays near Alistair","Maintains her weapons","Watches for threats","Preserves forge keepsakes"],"storyRole":"Herabelle serves as the graceful but dangerous shadow beside Alistair. Where his forgecraft and kinetic force dominate openly, she uses speed, precision, chains, and close-range attacks to control threats before they can reach him.","birthplace":"","psychology":["Idealizes Alistair","Misreads affection","Possessive attachment","Threat fixation","Extreme devotion"],"motivations":["Protect Alistair","Remain beside Alistair","Preserve his creations","Eliminate threats"],"personality":["Devoted","Protective","Possessive","Obsessive","Elegant","Patient","Ruthless","Jealous"],"voiceSpeech":["Soft","Melodic","Tender with Alistair","Cold toward threats","Guttural when enraged"],"likesDislikes":["Alistair''s craftsmanship","Alistair''s attention","Forge keepsakes","Protecting Alistair","Disrespect toward Alistair","Threats toward Alistair"],"majorLifeEvents":"Became Alistair''s devoted protector\nReceived Soul-Tether\nReceived Heart-Seeker"}','{"weapons":"Soul-Tether\nHeart-Seeker","strengths":"Speed\nAgility\nPrecision\nWeapon control\nBattlefield control\nProtective instinct","weaknesses":"Obsessive attachment\nJealousy\nEmotional instability\nPossessiveness","combatStyle":["Macabre Acrobat","Chain combat","Acrobatic movement","Precision strikes","Protective interception","Battlefield herding"],"limitations":["Emotion can override judgment","Overprotective of Alistair"],"powerSource":["Combat training","Alistair-forged weapons"],"abilityNotes":"Her combat choreography should appear graceful and rhythmic even at maximum aggression. Soul-Tether creates broad sweeping movements and unusual attack angles, while Heart-Seeker provides compact precision at close range.\n\nHerabelle is her canonical name. Do not use Lyra.","combatProfile":"Herabelle fights through finesse rather than overwhelming force. Soul-Tether controls distance and enemy movement while Heart-Seeker handles close-range precision attacks. She uses fluid acrobatics to herd enemies toward Alistair''s attacks and will physically intercept threats directed at him.","weaponDetails":"Soul-Tether is a long chained weapon crafted by Alistair for battlefield control. Its chain, crescent cutting head, and weighted component allow Herabelle to bind, trip, slow, and manipulate enemy movement. Heart-Seeker is a jagged, ultra-sharp serrated blade forged from Alistair''s kinetic-absorbing metal for close-range precision and dismantling. Herabelle carries both weapons with intense affection because Alistair made them.","transformations":"","primaryAbilities":"Chain Weapon Mastery\nBlade Mastery\nAcrobatic Combat\nEnemy Restraint\nPrecision Dismantling","secondaryAbilities":"Battlefield Control\nRapid Repositioning\nProtective Interception\nTarget Tracking","signatureTechniques":"Kinetic Synchronization\nSadist''s Grace\nHuman Shield","transformationDetails":""}','{"allies":"Alistair","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"","relationshipNotes":"Alistair is the center of Herabelle''s devotion. She views him and his forgecraft with almost religious reverence and frequently interprets practical praise or affection from him as something deeper. Soul-Tether and Heart-Seeker are especially precious to her because Alistair forged them."}','{"tbdFields":"Birth date\nExact age\nBirthplace\nHomeland\nCurrent residence\nParents\nSiblings\nLineage\nHeritage\nNationality\nHeight\nWeight\nDominant hand\nPartner status\nFormal affiliation","canonLocks":"Name is Herabelle\nFemale\nHuman\nBlonde hair\nGreen eyes\nBeautiful appearance\nDevoted to Alistair\nSoul-Tether\nHeart-Seeker\nWeapons forged by Alistair\nCarries her weapons with love","galleryUrl":"","mediaNotes":"Established artwork includes character portraits, a full-body combat design, visual production material, Soul-Tether and Heart-Seeker references, combat imagery, and promotional artwork. Future artwork must preserve the established blonde-haired, green-eyed Herabelle design.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b317848b-4cba-46fa-8807-4c9ffd26392e/portrait/1790364033055-herabelle-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Needed\nOutfit Breakdown — Done\nWeapon Reference — Done\nExpression Sheet — Done\nCombat Reference — Done","productionNotes":"Preserve Herabelle''s established blonde hair, green eyes, fair complexion, feminine face, slender athletic build, and neutral medieval-fantasy combat clothing. Soul-Tether and Heart-Seeker must follow their established visual references. Her design should emphasize beauty and elegance while allowing her obsessive combat persona to create a dramatic visual contrast.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b317848b-4cba-46fa-8807-4c9ffd26392e/reference/1790364038492-herabelle-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b317848b-4cba-46fa-8807-4c9ffd26392e/alternate/1790364048033-herabelle-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b317848b-4cba-46fa-8807-4c9ffd26392e/portrait/1790364033055-herabelle-character-portrait.png',6,1,1,NULL,'c68d60d1-883a-4683-8000-a9cd9d0d4d2a',NULL,NULL,'2026-09-25T19:27:20.760561+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('2db0849d-a110-403b-a442-42bab2a31f6f','db618e68-0656-4b9b-b308-81e071faf745','Gaius','complete','{"age":"","era":"500–1300 AD-inspired","name":"Gaius","race":"Elemental Dragon","alias":"The Sand Dragon","gender":"Male","titles":"Warden of the Wastes","subrace":"","summary":"Gaius is the Sand Dragon, born from the elemental union of Earth and Air. Calm, observant, and fiercely independent, he wanders the shifting deserts as a solitary warden. His power embodies erosion: the gradual reduction of even the strongest structures into countless moving grains.","heritage":"Indian + White","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Warden of the Wastes","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Shifting Sands","elementalHeritage":"Earth + Air"}','{"build":["Tall","Lean-muscular","Broad-shouldered"],"nails":"","eyeHex":["Golden Amber — #D89A32"],"height":"","makeup":"","weight":"","hairHex":["Black — #171313"],"skinHex":["Warm Brown — #9A6848"],"eyeColor":["Golden amber"],"grooming":"Natural","skinTone":["Warm medium-brown"],"wardrobe":"Layered desert wraps\nFlowing drapes\nLoose trousers\nFace wraps\nLeather waist layers","hairColor":["Black"],"hairStyle":"Tousled medium-length hair","accessories":"Gold earrings\nBronze arm cuffs\nLayered waist belts\nDesert face wrap","faceDetails":["Angular features","Defined jawline"],"hairTexture":["Wavy","Thick"],"colorPalette":"Sand — #D6B07A\nDune Gold — #C78B3B\nCopper — #9B5D2E\nDeep Brown — #4A3025\nDesert Cream — #E6D7BC","dominantHand":"","outfitColors":"Beige\nCopper\nDeep gold\nBrown","alternateForm":["Sand Dragon Form"],"clothingStyle":"Practical early-medieval desert attire designed for heat, wind, dust, and long-distance travel. Gaius favors loose layers that move naturally with the wind and can be rearranged for protection during sandstorms.","appearanceNotes":"His human design carries a distinctly nomadic desert silhouette with flowing layers and minimal rigid armor. His clothing should appear weathered and functional while retaining subtle gold ornamentation.","outfitMaterials":["Linen","Leather","Bronze","Gold"],"postureMovement":["Relaxed","Quiet","Fluid"],"signatureOutfit":"Layered desert wraps with flowing linen drapes, loose trousers, wrapped footwear, leather waist layers, and a protective face wrap. Gold and bronze accessories add restrained ornamentation without sacrificing mobility.","distinguishingFeatures":["Desert face wrap"]}','{"fears":"","goals":["Guard the elemental borders","Preserve the wastes"],"beliefs":["Power does not require recognition","Change is inevitable"],"culture":"","lineage":"Primal Earth + Primal Air","storyArc":"","backstory":"Born to Terrax and Atherous, Gaius inherited the physical mass of Earth and the relentless velocity of Air. Their combined forces manifested as sand and erosion rather than solid stone or open wind. He eventually chose a solitary existence among the vast dunes, distancing himself from elemental family conflicts.","childhood":"","lifestyle":["Nomadic","Solitary","Desert wandering","Border guarding"],"storyRole":"Gaius serves as a quiet border guardian between the mortal world and the dangerous territories of the Primal Dragons. His isolation allows him to occupy a neutral position within volatile elemental family conflicts.","birthplace":"","psychology":["Values independence","Avoids family drama","Dislikes confinement","Prefers observation"],"motivations":["Protect the desert borders","Maintain independence","Prevent mortal trespassing"],"personality":["Calm","Observant","Independent","Reserved","Patient","Detached"],"voiceSpeech":["Quiet","Measured","Reserved"],"likesDislikes":["Likes solitude","Likes open deserts","Likes quiet","Dislikes loud egos","Dislikes confinement","Dislikes unnecessary conflict"],"majorLifeEvents":"Became Warden of the Wastes"}','{"weapons":"","strengths":"Physical attack evasion\nArea control\nAttrition combat\nEnvironmental manipulation\nArmor erosion\nBody reformation","weaknesses":"","combatStyle":["Patient","Defensive","Attrition-based","Area control","Indirect"],"limitations":["Extreme heat fuses sand into glass"],"powerSource":["Earth","Air","Sand"],"abilityNotes":"Gaius can disperse his physical body into sand, allowing conventional physical attacks to pass through him. Extreme heat can fuse his sand into glass, which he can manipulate into cages, barriers, jagged formations, or shattered projectiles. His sand combines Earth''s physical matter with Air''s velocity.","combatProfile":"Gaius avoids brute-force exchanges and gradually controls the battlefield through sandstorms, erosion, blindness, suffocation, and friction. He can dissolve into billions of grains to evade physical attacks and reform elsewhere. His high-speed sand can gradually strip protective material from targets.","weaponDetails":"","transformations":"Sand Dragon Form","primaryAbilities":"Sand Manipulation\nErosion Manipulation\nSand Dissolution\nSandstorm Generation","secondaryAbilities":"Mirage Creation\nFriction Manipulation\nSuffocation\nGlass Creation\nBody Reformation","signatureTechniques":"Mirage & Dissolution\nSuffocation & Friction\nGlass Creation","transformationDetails":"Gaius becomes a massive dragon composed of compressed golden-brown sand, silica, and quartz. His scales continuously grind and shift like moving dunes, while portions of his wings and tail dissolve into a perpetual sandstorm. His crystalline gold eyes remain completely solid and motionless while the rest of his body constantly shifts."}','{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"","relationshipNotes":""}','{"tbdFields":"","canonLocks":"","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/2db0849d-a110-403b-a442-42bab2a31f6f/portrait/1790360157683-gaius-character-portrait.png","visualAssets":"","productionNotes":"","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/2db0849d-a110-403b-a442-42bab2a31f6f/reference/1790360166812-gaius-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/2db0849d-a110-403b-a442-42bab2a31f6f/alternate/1790360177853-gaius-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/2db0849d-a110-403b-a442-42bab2a31f6f/portrait/1790360157683-gaius-character-portrait.png',6,1,1,'48066562-cd1c-4b72-8c29-399594efad38','f6cff800-4029-4f02-b391-098583082feb',NULL,'65ff1f49-c1fc-4599-93a6-fe6a49a4c4d5','2026-09-25T18:27:16.828989+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('ccc902c8-99ac-442c-b404-783996e7218e','db618e68-0656-4b9b-b308-81e071faf745','Lord Alistar Vane','complete','{"age":"Mid 30s","era":"","name":"Lord Alistar Vane","race":"","alias":"The Architect of Tomorrow","gender":"Male","titles":"The Technical Forgemaster","subrace":"","summary":"A charismatic and brilliant technical forgemaster whose approachable personality contrasts sharply with the dangerous potential of his inventions. Alistar channels kinetic force through glowing golden runes and approaches creation with infectious enthusiasm.","heritage":"","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Technical Forgemaster","affiliation":"","apparentAge":"","canonStatus":"","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":""}','{"build":["Broad-shouldered","Muscular arms"],"nails":"","eyeHex":"","height":"6''1\"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Copper-gold"],"grooming":"Frequently forgets to brush his hair","skinTone":"","wardrobe":"Elegant coats\nRolled-sleeve shirts\nLeather harnesses\nReinforced gloves\nForge boots","hairColor":["Dark auburn"],"hairStyle":"Messy and usually tied back","accessories":"Forge goggles","faceDetails":["Strong jaw","Slightly crooked nose","Warm smile","Approachable expression"],"hairTexture":"","colorPalette":"","dominantHand":"","outfitColors":"","alternateForm":"","clothingStyle":"Noble attire blended with practical workshop clothing.","appearanceNotes":"His bright, intelligent eyes are constantly moving and analyzing. When excited, his copper-gold eyes appear to sparkle.","outfitMaterials":["Leather"],"postureMovement":"","signatureOutfit":"Rolled sleeves, leather harness, reinforced gloves, heavy forge boots, goggles around his neck, and an elegant coat over functional workshop gear.","distinguishingFeatures":["Loose face-framing strands"]}','{"fears":"","goals":"","beliefs":"","culture":"","lineage":"","storyArc":"","backstory":"","childhood":"","lifestyle":["Forging","Inventing","Workshop experimentation"],"storyRole":"","birthplace":"","psychology":["Constantly analyzing","Excitable about inventions","Underestimates his creations'' danger"],"motivations":["Innovation","Creation"],"personality":["Charismatic","Friendly","Brilliant","Approachable","Enthusiastic","Inventive","Absent-minded"],"voiceSpeech":"","likesDislikes":["Creating inventions","Technical experimentation"],"majorLifeEvents":""}','{"weapons":"","strengths":"Technical brilliance\nForging expertise\nInventive engineering\nPhysical strength","weaknesses":"Underestimates invention hazards","combatStyle":"","limitations":"","powerSource":["Kinetic Imbuement"],"abilityNotes":"When Alistar channels kinetic power, golden runes ignite beneath his skin. Nearby tools vibrate, weapons hum, and the surrounding air crackles with restrained force.","combatProfile":"","weaponDetails":"","transformations":"","primaryAbilities":"Kinetic Imbuement","secondaryAbilities":"Kinetic rune manifestation","signatureTechniques":"","transformationDetails":""}','{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"","relationshipNotes":""}','{"tbdFields":"","canonLocks":"Dark auburn hair\nCopper-gold eyes\nMessy tied-back hairstyle\nBroad muscular build\nStrong jaw\nSlightly crooked nose\nWarm smile\nForge goggles\nGolden kinetic runes","galleryUrl":"","mediaNotes":"Anime-style visual design established.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/ccc902c8-99ac-442c-b404-783996e7218e/portrait/1790360559565-ailstar-character-portrait.png","visualAssets":"Character Portrait — Done","productionNotes":"Preserve his dark auburn tied-back hair, loose face-framing strands, copper-gold eyes, broad muscular build, forge goggles, leather harness, rolled sleeves, reinforced gloves, heavy forge boots, elegant outer coat, and golden kinetic rune effects.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/ccc902c8-99ac-442c-b404-783996e7218e/reference/1790360575346-ailstar-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/ccc902c8-99ac-442c-b404-783996e7218e/alternate/1790360586376-ailstar-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/ccc902c8-99ac-442c-b404-783996e7218e/portrait/1790360559565-ailstar-character-portrait.png',6,1,1,NULL,NULL,NULL,NULL,'2026-09-25T18:27:15.710822+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('5de8dc77-a4f2-4117-8c92-105cfd9b2cd8','db618e68-0656-4b9b-b308-81e071faf745','Lord Corvin Sterling','complete','{"age":"Mid to late 30s","era":"","name":"Lord Corvin Sterling","race":"","alias":"The Man Who Forgets Nothing","gender":"Male","titles":"Intelligence Master","subrace":"","summary":"An unassuming intelligence master whose perfect memory and exceptional observational skills make him quietly formidable. Corvin rarely commands attention; instead, he absorbs everything around him. His calm demeanor contrasts with the unsettling realization that he remembers nearly everything he sees and hears.","heritage":"","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Intelligence Master","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":""}','{"build":["Thin"],"nails":"","eyeHex":"","height":"5''11\"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Warm amber"],"grooming":"Practical","skinTone":["Fair"],"wardrobe":"Practical noble attire\nLayered clothing\nTravel cloaks","hairColor":["Dark brown"],"hairStyle":"Short and practical","accessories":"Glasses\nLeather gloves\nWhistles\nCarved animal tokens","faceDetails":["Soft jawline","Slightly tired eyes","Thin lips","Understatedly handsome"],"hairTexture":"","colorPalette":"","dominantHand":"","outfitColors":"","alternateForm":"","clothingStyle":"Functional noble clothing designed for travel, observation, and discreet storage rather than display.","appearanceNotes":"Corvin looks surprisingly ordinary and does not naturally command attention. His warm eyes initially appear comforting, but prolonged eye contact becomes unsettling once his flawless recall and observational ability are understood.","outfitMaterials":["Leather"],"postureMovement":["Unassuming","Quiet","Observant"],"signatureOutfit":"Layered practical noble attire with a travel cloak, leather gloves, concealed pockets, and glasses when reviewing reports.","distinguishingFeatures":""}','{"fears":"","goals":"","beliefs":"","culture":"","lineage":"","storyArc":"","backstory":"","childhood":"","lifestyle":"","storyRole":"Corvin serves as an intelligence specialist whose extraordinary memory allows him to retain conversations, behaviors, inconsistencies, and subtle details others overlook.","birthplace":"","psychology":["Highly perceptive","Constantly observant","Detail-oriented"],"motivations":"","personality":["Calm","Reserved","Observant","Patient","Quiet","Analytical"],"voiceSpeech":["Soft-spoken","Controlled","Rarely raises his voice"],"likesDislikes":["Animals"],"majorLifeEvents":""}','{"weapons":"","strengths":"Perfect recall\nExceptional observation\nBehavioral analysis\nAnimal affinity\nInformation retention","weaknesses":"","combatStyle":"","limitations":"","powerSource":"","abilityNotes":"Perfect Memory Recall allows Corvin to retain extraordinary amounts of observed and spoken information. His attention to microexpressions, inconsistencies, and breathing patterns makes even ordinary conversations valuable sources of intelligence. His Beast Tamer affinity creates an unusually strong rapport with animals.","combatProfile":"","weaponDetails":"","transformations":"","primaryAbilities":"Perfect Memory Recall\nBeast Taming","secondaryAbilities":"Microexpression Reading\nBehavioral Observation\nInconsistency Detection\nBreathing Pattern Analysis","signatureTechniques":"","transformationDetails":""}','{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"","relationshipNotes":""}','{"tbdFields":"","canonLocks":"Warm amber eyes\nDark brown hair\nShort practical hairstyle\nThin build\n5''11\" height\nSoft jawline\nSlightly tired eyes\nThin lips\nPractical noble attire\nGlasses\nLeather gloves","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/5de8dc77-a4f2-4117-8c92-105cfd9b2cd8/portrait/1790360678101-corvin-character-portrait.png","visualAssets":"Character Portrait — Done","productionNotes":"Anime-style visual design. Preserve his understated appearance, thin build, short dark brown hair, warm amber eyes, practical noble clothing, glasses, leather gloves, and Beast Tamer accessories.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/5de8dc77-a4f2-4117-8c92-105cfd9b2cd8/reference/1790360695453-corvin-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/5de8dc77-a4f2-4117-8c92-105cfd9b2cd8/alternate/1790360714190-corvin-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/5de8dc77-a4f2-4117-8c92-105cfd9b2cd8/portrait/1790360678101-corvin-character-portrait.png',6,1,1,NULL,NULL,NULL,NULL,'2026-09-25T18:27:13.755287+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('6d00acef-a778-40bb-bfdc-f72787d0168f','db618e68-0656-4b9b-b308-81e071faf745','Zafir','complete','{"age":"","era":"","name":"Zafir","race":"Half-Genie / Half-Human","alias":"The Infinite Conjurer","gender":"Male","titles":"Wild Card","subrace":"Half-Genie","summary":"Zafir is a Half-Genie and Half-Human Sunspear whose impossible birth was made possible by his mother''s Great Wish. His father''s entire Genie essence was woven into Zafir''s soul to sustain his existence. Charismatic, theatrical, and effortlessly confident, Zafir travels with Kaelen''s crew while searching for the Lamp of the First Djinn and a way to separate his father''s essence from his own.","heritage":"Sunspear","homeland":"Shifting Sands","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Conjurer","affiliation":"Kaelen''s Crew","apparentAge":"Early 20s","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":""}','{"build":["Short","Lean","Athletic"],"nails":"","eyeHex":"","height":"5''4\"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Golden amber"],"grooming":"Well-groomed","skinTone":["Warm bronze"],"wardrobe":"Sleeveless embroidered vests\nHarem pants\nRoyal Sunspear silks\nFlowing waist fabrics","hairColor":["Mint-blue"],"hairStyle":"Voluminous gravity-defying waves","accessories":"Gold bangles\nJeweled waist-cinch\nSapphire earring\nGold necklace","faceDetails":["Sharp features","Handsome face","Almond-shaped eyes"],"hairTexture":["Thick"],"colorPalette":"Mint Blue\nCerulean\nSilver\nTeal\nGold\nWarm Bronze","dominantHand":"","outfitColors":"Teal\nGold\nBlack\nWhite","alternateForm":["Mist Form","Miniature Form"],"clothingStyle":"Opulent Sunspear clothing designed for unrestricted movement and aerial poses. Open-chested garments deliberately leave his Genie markings visible.","appearanceNotes":"Zafir''s blue markings extend from the crown of his head to the soles of his feet and pulse when he channels magic. His hair and loose fabrics subtly drift as though suspended underwater. He commonly hovers several inches above the ground, making his short stature less immediately apparent.","outfitMaterials":["Silk","Gold embroidery","Sheer fabric"],"postureMovement":["Persistent hovering","Fluid movement","Weightless movement","Relaxed floating poses"],"signatureOutfit":"A short sleeveless embroidered vest worn over a bare chest with high-waisted teal harem pants, gold jewelry, and flowing Sunspear fabrics.","distinguishingFeatures":["Glowing blue Genie markings"]}','{"fears":["Losing his father permanently","Being exploited as an artifact","Losing his identity","Having his wishes abused"],"goals":["Find the Lamp of the First Djinn","Untangle his father''s essence","Meet his father","Understand the Shifting Sands"],"beliefs":["Wishes should carry meaning","Greed destroys people","Freedom is essential","Sacrifice gives wishes value"],"culture":["Sunspear","Navigator"],"lineage":"Sunspear","storyArc":"Zafir''s search for the Lamp of the First Djinn forces him to confront whether becoming whole requires separating himself from the father whose essence helped create him. His journey through the Shifting Sands becomes both a search for his father and an exploration of his own identity.","backstory":"Genies normally cannot reproduce with mortals. Zafir''s mother used her final Great Wish to conceive a child with the Genie she loved. The wish required Zafir''s father''s entire essence to be woven into Zafir, leaving the boy carrying both his own soul and his father''s essence. Zafir eventually began searching for the Lamp of the First Djinn in hopes of untangling them.","childhood":"Zafir was raised by his mother in a village of Master Navigators within the Shifting Sands. He learned Sunspear combat, star-mapping, desert survival, and how to read signs associated with Gaius and Ruchika. His unusual Genie traits made him both valuable to the village and a target for Desert Raiders.","lifestyle":["Prefers hovering to walking","Enjoys social settings","Explores ancient ruins","Searches magical nexuses","Avoids unnecessary physical labor"],"storyRole":"Zafir serves as the charismatic wild card of Kaelen''s crew. His reality-warping abilities provide extraordinary versatility, while his knowledge of the Shifting Sands makes him essential when the crew enters Genie territory.","birthplace":"Shifting Sands","psychology":["Feels divided between two identities","Masks insecurity with confidence","Values personal freedom","Distrusts greed","Protective of his wish magic"],"motivations":["Understand his Genie heritage","Restore his father","Protect his autonomy","Prevent misuse of wishes"],"personality":["Charismatic","Confident","Enigmatic","Romantic","Playful","Witty","Theatrical","Selective","Stylish","Detached"],"voiceSpeech":["Speaks in third person","Smooth delivery","Playful teasing","Elegant phrasing","Slightly theatrical"],"likesDislikes":["Beautiful things","Stories","Teasing Sax","Jasmine","Stargazing","Greed","Confinement","Being underestimated","Wasted wishes"],"majorLifeEvents":"Born through the Great Wish\nFather''s essence merged with his soul\nRaised among the Master Navigators\nBecame a Navigator scout\nTargeted by Desert Raiders\nJoined Kaelen''s Crew\nBegan searching for the First Djinn''s Lamp"}','{"weapons":"","strengths":"Extreme magical versatility\nAerial mobility\nMatter alteration\nPhysical evasion\nTangible conjuration\nDesert navigation\nSocial manipulation","weaknesses":"Severe post-wish exhaustion\nVulnerability after granting wishes","combatStyle":["Aerial combat","Sunspear combat","Reality manipulation","Transmutation","Conjured weapons","Evasive combat"],"limitations":["One wish per person per lifetime","Cannot grant his own wishes","Wish granting drains Chronoessence"],"powerSource":["Genie essence","Internal Chronoessence"],"abilityNotes":"Zafir''s magic is internal rather than drawn from an external Chronoessence source. His conjurations emerge through mint-blue mist accompanied by the scent of jasmine and ozone. His One-Wish Rule allows him to grant one wish to each person during that person''s lifetime, but fulfilling a wish severely depletes his Chronoessence and can leave him vulnerable for several days.","combatProfile":"Zafir fights from the air whenever possible, using mobility and unpredictability rather than remaining in direct exchanges. He alters matter, creates tangible phantasms, and shifts into mist to evade attacks. His Sunspear training gives him a grounded combat foundation when magic is unavailable.","weaponDetails":"","transformations":"Mist Form\nMiniature Form\nShapeshifted Forms","primaryAbilities":"Conjuration\nTransmutation\nMaterial Manipulation\nPhantasm Creation\nIntangibility\nFlight","secondaryAbilities":"Shapeshifting\nMiniaturization\nMist Transformation\nDesert Hazard Sensing\nTemporal Dust Detection","signatureTechniques":"One-Wish Rule\nHard-Light Conjuration\nMist Form\nMiniature Form","transformationDetails":"Zafir can dissolve his physical body into a gaseous mist capable of bypassing barriers and physical attacks. He can also transmute himself into animals, other people, or a miniature version of himself while retaining his personality and magical nature."}','{"allies":"Kaelen\nSax","rivals":"Sax","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"Shifting Sands\nShifting Citadel\nLamp of the First Djinn","relationshipNotes":"Zafir''s unnamed Genie father sacrificed his separate existence during the Great Wish that created Zafir, leaving his essence woven into Zafir''s soul. His unnamed Sunspear mother raised him among the Navigators and taught him the story of his father''s sacrifice. Zafir shares a playful rivalry with Sax and frequently provokes him through teasing and effortless displays of magic."}','{"tbdFields":"Birth date\nExact age\nWeight\nDominant hand\nMother''s name\nFather''s name","canonLocks":"Warm bronze skin\nGolden amber eyes\nMint-blue hair\nGlowing blue Genie markings\n5''4\" height\nLean athletic build\nSunspear attire\nTeal and gold palette\nSapphire jewelry\nPersistent hovering","galleryUrl":"","mediaNotes":"The Reference / Production Sheet is the primary visual reference for future Zafir artwork.","galleryUrls":["https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/6d00acef-a778-40bb-bfdc-f72787d0168f/gallery/1790360795690-zafir-miniature-form.png"],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/6d00acef-a778-40bb-bfdc-f72787d0168f/portrait/1790360764956-zafir-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done","productionNotes":"Preserve Zafir''s warm bronze skin, mint-blue hair, golden amber eyes, glowing blue Genie markings, short lean build, and ornate Sunspear clothing. He should usually appear hovering rather than standing normally. Magic manifests through cerulean or mint-blue light, mist, and silver highlights.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/6d00acef-a778-40bb-bfdc-f72787d0168f/reference/1790360783492-zafir-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/6d00acef-a778-40bb-bfdc-f72787d0168f/alternate/1790360789805-zafir-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/6d00acef-a778-40bb-bfdc-f72787d0168f/portrait/1790360764956-zafir-character-portrait.png',6,1,1,'48066562-cd1c-4b72-8c29-399594efad38','0b60f4e0-6962-403f-9129-83fba60ab268','f5492e8b-d617-44b1-bce7-517c90d1da55','5390053d-91ee-4046-943f-d8008e4d5d0e','2026-09-25T18:27:12.7841+00:00');
